sys_script.script:
(function executeRule(current, previous) {
  var type = current.getValue('snapshot_type');
  var validTypes = ['coverage', 'trend', 'gap'];
  if (validTypes.indexOf(type) === -1) {
    gs.addErrorMessage("TestReach: snapshot_type must be one of: " + validTypes.join(', '));
    current.setAbortAction(true);
    return;
  }
  if (!current.getValue('app_scope')) {
    gs.addErrorMessage('TestReach: app_scope is required on coverage snapshot rows.');
    current.setAbortAction(true);
    return;
  }
  if (!current.getValue('artifact_sys_id')) {
    gs.addErrorMessage('TestReach: artifact_sys_id is required on coverage snapshot rows.');
    current.setAbortAction(true);
    return;
  }
  var pct = parseFloat(current.getValue('coverage_pct'));
  if (isNaN(pct) || pct < 0 || pct > 100) {
    current.setValue('coverage_pct', 0);
  }
  if (!current.getValue('snapshot_ts')) {
    current.setValue('snapshot_ts', new GlideDateTime());
  }
  var crit = parseInt(current.getValue('criticality'), 10);
  if (isNaN(crit) || crit < 1) current.setValue('criticality', 1);
  if (crit > 5) current.setValue('criticality', 5);
})(current, previous);
